<original_code>
import java.io.*;
import java.util.*;

public class TwentyFive {
    public static void main(String[] args) throws IOException {
        InputStreamReader isr = new InputStreamReader(System.in);
        BufferedReader br = new BufferedReader(isr);
        String pattern = br.readLine();
        int countMatches = 0;
        for (int num = 0; num < 100000000; num += 25) {
            String numStr = String.valueOf(num);
            if (numStr.length() != pattern.length()) continue;
            int xCharCode = -1;
            boolean match = true;
            for (int index = 0; index < pattern.length(); index++) {
                char pChar = pattern.charAt(index);
                char nChar = numStr.charAt(index);
                if (pChar == 'X') {
                    if (xCharCode == -1) {
                        xCharCode = nChar;
                    }
                    if (nChar != xCharCode) {
                        match = false;
                        break;
                    }
                } else if (pChar != '_') {
                    if (nChar != pChar) {
                        match = false;
                        break;
                    }
                }
            }
            if (match) countMatches++;
        }
        System.out.println(countMatches);
    }
}
